(()=>{
'use strict';
const E=x=>(window.esc?window.esc(x):String(x??''));
const status=t=>t.status||(t.done?'completed':'pending');
const today=()=>new Date().toISOString().slice(0,10);
function addHome(){if(window.currentTab!=='Início')return;const root=document.getElementById('view');if(!root||root.querySelector('.sbNow'))return;const tasks=Array.isArray(state.tasks)?state.tasks:[],open=tasks.filter(t=>status(t)!=='completed'),mine=open.filter(t=>t.assignee===me?.name),late=open.filter(t=>t.due&&t.due<today()),vis=(state.meetings||[]).flatMap(m=>m.presidencyVisits||[]).filter(v=>v.date&&v.date>=today()).sort((a,b)=>a.date.localeCompare(b.date));const n=document.createElement('section');n.className='sbNow';n.innerHTML=`<div class="sbKicker">Agora</div><div class="sbNowTop"><div><b>${open.length?open.length+' '+(open.length===1?'ação aberta':'ações abertas'):'Tudo acompanhado'}</b><small>${mine.length?mine.length+' '+(mine.length===1?'é sua':'são suas'):'Nenhuma ação atribuída a você'}</small></div>${late.length?`<span class="sbAlert">${late.length} atrasada${late.length>1?'s':''}</span>`:''}</div>${vis[0]?`<div class="sbNext"><span>Próxima visita</span><b>${E(vis[0].member||'Irmão')}</b><small>${window.dateBR?dateBR(vis[0].date):vis[0].date}${vis[0].time?' · '+E(vis[0].time):''}</small></div>`:''}`;root.prepend(n)}
function presidency(){if(window.currentTab!=='Presidência')return;const root=document.getElementById('view');if(!root||root.querySelector('.sbPres'))return;const open=(state.tasks||[]).filter(t=>status(t)!=='completed'&&t.sourceDate),meet=(state.meetings||[]).filter(m=>m.date||m.sourceDate).sort((a,b)=>(b.date||b.sourceDate).localeCompare(a.date||a.sourceDate)),last=meet[0],carry=last?open.filter(t=>t.sourceDate===(last.sourceDate||last.date)):[];if(!carry.length)return;const n=document.createElement('div');n.className='sbPres';n.innerHTML=`<span>Da reunião anterior</span><b>${carry.length} ${carry.length===1?'ação precisa':'ações precisam'} de acompanhamento</b><small>Pendentes e em andamento permanecem visíveis até serem concluídas.</small>`;const s=root.querySelector('.section');(s||root).insertAdjacentElement(s?'beforebegin':'afterbegin',n)}
function people(){if(window.currentTab!=='Irmãos')return;const root=document.getElementById('view');if(!root||root.querySelector('.sbSearch'))return;const n=document.createElement('div');n.className='sbSearch';n.innerHTML='<input type="search" placeholder="Buscar irmão" autocomplete="off">';const s=root.querySelector('.section');(s||root).insertAdjacentElement(s?'beforebegin':'afterbegin',n);n.firstElementChild.addEventListener('input',ev=>{const q=ev.target.value.trim().toLocaleLowerCase('pt-BR');root.querySelectorAll('.brother').forEach(x=>x.style.display=!q||x.textContent.toLocaleLowerCase('pt-BR').includes(q)?'':'none')})}
function semantics(){document.querySelectorAll('.actionsRow').forEach(x=>x.setAttribute('role','group'));document.querySelectorAll('button').forEach(b=>{if(!b.getAttribute('type'))b.type='button'});document.querySelectorAll('.scheduleToggle').forEach(b=>b.setAttribute('aria-expanded',b.closest('.scheduleRow')?.querySelector('.inlinePlan:not([hidden])')?'true':'false'))}
function run(){try{addHome();presidency();people();semantics()}catch(e){console.warn('safe bundle skipped enhancement',e)}}
const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);requestAnimationFrame(run);return r};document.addEventListener('DOMContentLoaded',()=>setTimeout(run,0));
const css=document.createElement('style');css.textContent=`.sbNow,.sbPres{background:var(--ios-card,#fff);border-radius:16px;padding:17px 18px;margin-bottom:14px;box-shadow:0 .5px 0 rgba(0,0,0,.06)}.sbKicker,.sbPres>span{display:block;color:var(--teal);font-size:10px;font-weight:750;letter-spacing:.055em;text-transform:uppercase;margin-bottom:5px}.sbNowTop{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.sbNowTop b,.sbNowTop small,.sbPres b,.sbPres small,.sbNext span,.sbNext b,.sbNext small{display:block}.sbNowTop b{font-size:20px;letter-spacing:-.02em}.sbAlert{background:#fff1e5;color:#9a531e;border-radius:999px;padding:5px 8px;font-size:11px;font-weight:700}.sbNext{border-top:.5px solid var(--ios-sep,var(--line));margin-top:14px;padding-top:12px}.sbNext span{font-size:11px;color:var(--mut);margin-bottom:3px}.sbPres b{font-size:16px;margin-bottom:3px}.sbSearch input{border:0!important;background:#e9e9ee!important;border-radius:12px!important;margin:0 0 14px!important;padding:11px 14px!important}.item{transition:opacity .15s ease}.item:has(select option[value="completed"]:checked){opacity:.62}@media(max-width:650px){.sbNow,.sbPres{border-radius:15px}.sbNowTop b{font-size:18px}}@media(prefers-color-scheme:dark){.sbSearch input{background:#2c2c2e!important;color:#fff!important}.sbAlert{background:#432b18;color:#ffc58f}}`;document.head.appendChild(css)
})();